let fleet=[],locations=[],mode='self',category='All';
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+n.toLocaleString('en-IN');
const rateFor=car=>mode==='self'?car.selfRate:car.driverRate;
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
const today=new Date(),tomorrow=new Date(today);tomorrow.setDate(today.getDate()+1);$('start-date').min=localDate(today);$('start-date').value=localDate(today);$('end-date').min=localDate(tomorrow);$('end-date').value=localDate(tomorrow);$('year').textContent=today.getFullYear();
function validDates(){const start=$('start-date').value,end=$('end-date').value;if(!start||!end||start<localDate(new Date())||end<=start){$('search-error').textContent='Choose a pick-up date from today and a return date after pick-up.';return false;}$('search-error').textContent='';return true;}
function visibleCars(){return fleet.filter(c=>(category==='All'||c.category===category)&&c.locationIds.includes($('city').value)&&(mode==='self'?c.selfEnabled:c.driverEnabled));}
function render(){const list=visibleCars(),city=locations.find(l=>l.id===$('city').value)?.name||'No active locations';$('result-count').textContent=`${list.length} ${list.length===1?'car':'cars'} · ${city} · ${mode==='self'?'Self-drive':'With a chauffeur'}`;$('cars').innerHTML=list.length?list.map(c=>`<article class="car-card"><div class="car-image">${carGallery(c)}<span class="car-tag">${esc(c.category.toUpperCase())}</span></div><div class="car-body"><div class="car-title"><h3>${esc(c.name)}</h3></div><div class="car-specs"><span>♙ ${c.seats} seats</span><span>◈ ${esc(c.category)}</span></div><div class="car-bottom"><div class="price">${rateFor(c)==null?'Request a quote':money(rateFor(c))+'<small> / day</small>'}</div><button class="ride-button" data-book="${esc(c.id)}">View ride</button></div></div></article>`).join(''):'<div class="empty">No cars are currently listed for this city and rental type. Try another selection or contact GoRide.</div>';}
function renderLocations(){const previous=$('city').value;$('city').innerHTML=locations.map(l=>`<option value="${esc(l.id)}">${esc(l.name)}</option>`).join('');if(locations.some(l=>l.id===previous))$('city').value=previous;$('city-grid').innerHTML=locations.map((l,i)=>`<button class="city-card" data-city="${esc(l.id)}"><span class="city-number">${String(i+1).padStart(2,'0')} / GORIDE</span><h3>${esc(l.name)}</h3><p>Your next journey starts here.</p><span class="city-action">Explore cars</span></button>`).join('');const names=locations.map(l=>l.name);$('hero-cities').textContent=names.join(' · ').toUpperCase();$('footer-cities').innerHTML=locations.map(l=>`<a href="#search" data-footer-city="${esc(l.id)}">${esc(l.name)} <span aria-hidden="true">↗</span></a>`).join('');$('cities-title').innerHTML=locations.length===3?'Three cities.<br>Countless detours<span>.</span>':'More places.<br>Countless detours<span>.</span>';$('find-button').disabled=!locations.length;}
function renderFilters(){const values=['All',...new Set(fleet.map(c=>c.category))];if(!values.includes(category))category='All';$('category-filters').innerHTML=values.map(c=>`<button class="filter ${category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${category===c}">${c==='All'?'All cars':esc(c==='Hatchback'?'Hatchbacks':c+'s')}</button>`).join('');}
async function loadCatalog(){try{const response=await fetch('/api/catalog',{cache:'no-store'});if(!response.ok)throw Error('Catalogue unavailable');const data=await response.json();fleet=data.cars;locations=data.locations;renderLocations();renderFilters();render();$('catalog-error').hidden=true;}catch{$('catalog-error').hidden=false;if(!fleet.length)$('cars').innerHTML='<div class="empty">Our cars could not be loaded. <button class="ride-button" id="retry-catalog">Try again</button> or call GoRide on 86102 35694.</div>';}}
document.querySelectorAll('.mode').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();}));$('category-filters').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;renderFilters();render();});$('city').addEventListener('change',render);
$('start-date').addEventListener('change',()=>{const d=new Date($('start-date').value+'T12:00:00');if(Number.isNaN(d.getTime()))return;d.setDate(d.getDate()+1);$('end-date').min=localDate(d);if($('end-date').value<localDate(d))$('end-date').value=localDate(d);});$('search-form').addEventListener('submit',e=>{e.preventDefault();if(validDates()){GoRideTrip.save({location:$('city').value,mode,startDate:$('start-date').value,endDate:$('end-date').value});render();$('fleet').scrollIntoView({behavior:'smooth'});}});$('city-grid').addEventListener('click',e=>{const b=e.target.closest('[data-city]');if(!b)return;$('city').value=b.dataset.city;render();$('search').scrollIntoView({behavior:'smooth'});});
function openTrip(id){if(!validDates()){$('search').scrollIntoView({behavior:'smooth'});return;}const car=visibleCars().find(c=>c.id===id);if(!car)return;const selection=GoRideTrip.save({car:car.id,location:$('city').value,mode,startDate:$('start-date').value,endDate:$('end-date').value});const days=Math.round((Date.parse($('end-date').value)-Date.parse($('start-date').value))/86400000),rate=rateFor(car),city=locations.find(l=>l.id===$('city').value)?.name;const fmt=s=>new Date(s+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});const row=(label,value)=>`<div class="trip-row"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`;$('booking-content').innerHTML=`<div class="dialog-eyebrow">YOUR TRIP, AT A GLANCE</div><h2>${esc(car.name)}</h2><p style="color:var(--muted);font-size:14px">${mode==='self'?'Self-drive. Your own pace.':'With a chauffeur. Enjoy the journey.'}</p><div class="trip-summary">${row('Pick-up city',city)}${row('Pick-up',fmt($('start-date').value))}${row('Return',fmt($('end-date').value))}${row('Duration',days+' '+(days===1?'day':'days'))}${row(rate==null?'Rental price':'Daily base rate',rate==null?'Request a quote':money(rate))}${rate==null?'':row('Base rental estimate',money(rate*days))}${car.deposit==null?'':row('Security deposit (separate)',money(car.deposit))}</div>${car.notes?`<p class="dialog-note">${esc(car.notes).replace(/\n/g,'<br>')}</p>`:''}<p class="dialog-note"><strong>This is a trip preview.</strong> No car is reserved and no payment is taken. Base rental estimates exclude any unlisted taxes, fuel, extra kilometres and driver allowances. Confirm your total, availability and terms with GoRide.</p><a class="primary" id="quote-link" target="_blank" rel="noopener noreferrer">Request quote on WhatsApp</a><a class="primary" href="${esc(GoRideTrip.url(selection))}" style="display:block;margin-top:12px;text-align:center">Send a booking request</a><button class="ride-button" id="done-preview" style="width:100%;margin-top:12px">Close preview</button>`;const message=`Hi GoRide, I would like a quote for ${car.name} in ${city}, ${mode==='self'?'self-drive':'with a chauffeur'}, from ${fmt($('start-date').value)} to ${fmt($('end-date').value)} (${days} ${days===1?'day':'days'}).${rate==null?'':' Listed base rental: '+money(rate*days)+'.'} Please confirm availability, total price, deposit and inclusions.`;$('quote-link').href='https://wa.me/919100852287?text='+encodeURIComponent(message);$('booking-dialog').showModal();$('done-preview').onclick=()=> $('booking-dialog').close();}
$('cars').addEventListener('click',e=>{if(e.target.closest('#retry-catalog'))loadCatalog();const b=e.target.closest('[data-book]');if(b)openTrip(b.dataset.book);});$('close-dialog').onclick=()=> $('booking-dialog').close();$('booking-dialog').addEventListener('click',e=>{if(e.target===$('booking-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
initHero();loadCatalog();window.addEventListener('focus',()=>{if(!$('booking-dialog').open)loadCatalog();});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'configure_car_search',title:'Configure car search',description:'Set GoRide city, rental mode and car category filters. Does not create a reservation.',inputSchema:{type:'object',properties:{city:{type:'string'},mode:{type:'string',enum:['self','driver']},category:{type:'string'}},required:['city','mode','category'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const l=locations.find(l=>l.id===input?.city||l.name===input?.city);if(!l||!['self','driver'].includes(input.mode)||!['All',...fleet.map(c=>c.category)].includes(input.category))throw Error('Invalid search filters');$('city').value=l.id;mode=input.mode;category=input.category;document.querySelector(`[data-mode="${mode}"]`).click();renderFilters();render();return {city:l.name,mode,category,resultCount:visibleCars().length,reservationCreated:false};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}

function photosFor(car){return [{url:car.image,credit:car.imageCredit},...(car.gallery||[])].filter(p=>p.url);}
function carGallery(car){const photos=photosFor(car);if(!photos.length)return '';return `<div class="car-gallery" data-gallery="${esc(car.id)}"><div class="gallery-track" tabindex="0" role="region" aria-label="${esc(car.name)} photos">${photos.map((p,i)=>`<img src="${esc(p.url)}" alt="${esc(car.name)} · photo ${i+1} of ${photos.length}" loading="lazy" draggable="false">`).join('')}</div>${photos.length>1?`<div class="gallery-controls"><button type="button" data-gallery-step="-1" aria-label="Previous photo of ${esc(car.name)}">‹</button><span class="gallery-count" aria-live="polite">1 / ${photos.length}</span><button type="button" data-gallery-step="1" aria-label="Next photo of ${esc(car.name)}">›</button></div>`:''}${photos.some(p=>p.credit)?`<a class="image-info" href="/image-information#${encodeURIComponent(car.id)}" aria-label="Image information for ${esc(car.name)}">i</a>`:''}</div>`;}
$('cars').addEventListener('click',event=>{const button=event.target.closest('[data-gallery-step]');if(!button)return;const track=button.closest('.car-gallery').querySelector('.gallery-track'),width=track.clientWidth,index=Math.round(track.scrollLeft/width),count=track.children.length;track.scrollTo({left:((index+Number(button.dataset.galleryStep)+count)%count)*width,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});});
$('cars').addEventListener('scroll',event=>{const track=event.target;if(!track.classList?.contains('gallery-track'))return;const label=track.closest('.car-gallery').querySelector('.gallery-count');if(label)label.textContent=(Math.round(track.scrollLeft/track.clientWidth)+1)+' / '+track.children.length;},true);
$('cars').addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key)||!event.target.classList?.contains('gallery-track'))return;event.preventDefault();const track=event.target,count=track.children.length,index=Math.round(track.scrollLeft/track.clientWidth);track.scrollTo({left:((index+(event.key==='ArrowRight'?1:-1)+count)%count)*track.clientWidth,behavior:'instant'});});
async function initHero(){try{const images=await(await fetch('/assets/images.json')).json(),photos=[images.hero,...(images.heroGallery||[])].filter(p=>p?.url);let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;const hero=document.querySelector('.hero'),picture=$('hero-image');let hover=false;
$('hero-dots').innerHTML=photos.map((p,i)=>`<button type="button" aria-label="Show car photo ${i+1}" aria-pressed="${i===index}" data-hero-slide="${i}"></button>`).join('');
photos.slice(1).forEach(photo=>{const preload=new Image();preload.src=photo.url;});
function show(next){index=(next+photos.length)%photos.length;picture.style.backgroundImage=`url("${photos[index].url}")`;$('hero-dots').querySelectorAll('button').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)));}
function pauseLabel(){$('hero-pause').textContent=paused?'Play slideshow':'Pause slideshow';$('hero-pause').setAttribute('aria-pressed',String(paused));}
$('hero-dots').onclick=event=>{const button=event.target.closest('[data-hero-slide]');if(button)show(Number(button.dataset.heroSlide));};$('hero-pause').onclick=()=>{paused=!paused;pauseLabel();};hero.addEventListener('mouseenter',()=>hover=true);hero.addEventListener('mouseleave',()=>hover=false);hero.addEventListener('focusin',()=>hover=true);hero.addEventListener('focusout',event=>{if(!hero.contains(event.relatedTarget))hover=false;});
const motion=matchMedia('(prefers-reduced-motion: reduce)');motion.addEventListener('change',()=>{if(motion.matches){paused=true;pauseLabel();}});show(0);pauseLabel();if(photos.length<2){document.querySelector('.hero-slideshow').hidden=true;return;}const timer=setInterval(()=>{if(!paused&&!hover&&!document.hidden)show(index+1);},6000);window.addEventListener('pagehide',()=>clearInterval(timer),{once:true});}catch{}}

async function refreshCustomerHeader(){
const link=document.getElementById('customer-header-link');if(!link)return;
try{const response=await fetch('/api/customer/session',{credentials:'same-origin',cache:'no-store'});
if(response.ok){const session=await response.json(),name=String(session.displayName||'Rider');link.textContent='Hi, '+name.charAt(0).toUpperCase()+name.slice(1);link.href='/account';link.title='Your GoRide account';link.setAttribute('aria-label',link.textContent+' · Open your account');link.classList.add('customer-signed-in');}
else if(response.status===401){link.textContent='Sign in';link.href='/login';link.setAttribute('aria-label','Sign in to GoRide');link.classList.remove('customer-signed-in');}
}catch{/* Keep the account link available when the session check is offline. */}}
refreshCustomerHeader();window.addEventListener('pageshow',refreshCustomerHeader);window.addEventListener('focus',refreshCustomerHeader);

document.querySelector('.goride-footer').addEventListener('click',e=>{const cityLink=e.target.closest('[data-footer-city]'),modeLink=e.target.closest('[data-footer-mode]');if(cityLink){$('city').value=cityLink.dataset.footerCity;render();}if(modeLink)document.querySelector(`.mode[data-mode="${modeLink.dataset.footerMode}"]`).click();});
